// === Tab: mySketch ===
var p = [];

function setup() {
	createCanvas(windowWidth, windowHeight);
	noStroke();
}

function mouseClicked() {
	for (i = 0; i < 50; i++) {
		p.push(new Particle);
	}
}

function draw() {
	background(0, 5);
	for (i = 0; i < p.length; i++) {
		p[i].show();
		p[i].move();
	}
}

// === Tab: Class ===
class Particle {
	constructor() {
		this.x = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)));
		this.xSpeed = random(-5, 5);
		this.y = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)));
		this.ySpeed = random(-10);
		this.invis = 255;

	}

	show() {
		fill(255, this.invis);
		ellipse(this.x, this.y, 5, 5);
	}
	move() {
		if (this.y >= windowHeight - 2.5) {
			this.y = windowHeight - 2.5;
			this.ySpeed = 0;
			this.invis = this.invis - 2;

		} else {
			this.ySpeed = this.ySpeed + 0.1;
		}
		this.x = this.x + this.xSpeed;
		this.y = this.y + this.ySpeed;
	}
}

